def replace_para(p, text):
    # Retain the original paragraph style, keep settings, and strip only old run content.
    p.clear()
    p.add_run(text)

def build_main():
    doc=Document(OUT/'Physical_AI_Psychiatry_Manuscript_v4.4.docx')
    assert len(doc.paragraphs)==149, len(doc.paragraphs)
    for i,new in REPL.items():
        replace_para(doc.paragraphs[i],new)
    # Begin the compact pathway table as a whole, avoiding a final row split.
    doc.paragraphs[14].paragraph_format.page_break_before = True
    # Keep the short four-pathway summary together at a page boundary.
    for row in doc.tables[0].rows[:-1]:
        for cell in row.cells:
            for paragraph in cell.paragraphs:
                paragraph.paragraph_format.keep_with_next=True
    for j,ref in enumerate(NEWREFS):
        p=doc.add_paragraph(ref)
        p.paragraph_format.left_indent=Inches(.2)
        p.paragraph_format.first_line_indent=Inches(-.2)
        p.paragraph_format.space_after=Pt(2)
        p.paragraph_format.line_spacing=1
        for r in p.runs:r.font.size=Pt(9.2)
    p=doc.paragraphs[4]
    words=re.findall(r"\b[\w]+(?:[-–][\w]+)*\b",p.text)
    if len(words)>150: raise ValueError(f'Abstract length {len(words)} exceeds 150 words')
    if len(TITLE.split())>15 or re.search(r'[:;,\-]',TITLE):raise ValueError('Noncompliant title')
    dest=OUT/'Physical_AI_Psychiatry_Manuscript_v4.5.docx'
    doc.save(dest)
    # Author-review copy retains the exact preferred title, with identical body text.
    replace_para(doc.paragraphs[0],OLD_TITLE)
    doc.save(OUT/'Physical_AI_Psychiatry_Author_Title_Review_v4.5.docx')
    return dest, len(words)

def build_supp():
    doc=Document(OUT/'Physical_AI_Psychiatry_Supplementary_Information_v4.4.docx')
    replacements={
        2:'Supplementary numerical contrasts and complete input provenance. The main manuscript contains all mathematical and operational Methods. Comprehensive parameter dictionaries are supplied as Supplementary Data 1–2, alongside reproducibility matrices and estimator diagnostics.',
        7:'The endpoint estimand module uses a separate deterministic seed stream from the primary contrasts. Its independent paired-replication intervals describe variation under the same declared parameter settings.',
        10:'Screen intake capacity is fixed across this comparison. Independent deterministic seeds explain the small difference between the three-station sensitivity estimate and the primary three-station estimate.',
        13:'These single-block substitutions are nonadditive pathway diagnostics. They use 120 repeated model trials with separately defined random streams and parameter substitutions.',
        16:'Primary and sensitivity estimates use separate Monte Carlo draws at identical specified parameter settings. Differences of this scale are consistent with ordinary finite-replication sampling variation.',
        21:'Exact Sobol contributions satisfy 0 ≤ S1 ≤ ST ≤ 1 and ΣS1 ≤ 1. The table preserves finite-design estimates and provides their accompanying diagnostics; small inconsistent terms are excluded from substantive interpretation.',
        23:'Supplementary Data 1–2 document each parameter by unit, functional role, reference pathway, range, evidence type, and calibration status. Literature citations are assigned where they support a specific scale, mechanism, or parameter-selection rationale. Numerical coefficients without an empirical source are explicitly designated as scenario assumptions. Display values are rounded consistently while executable configurations preserve full numerical precision.',
        24:'Numbered citations in the parameter dictionaries correspond to the complete [1–48] reference list in the main manuscript. Preprints are identified as such in their bibliography entries.'
    }
    for i,p in enumerate(doc.paragraphs):
        if p.text.strip()==OLD_TITLE: replace_para(p,TITLE)
        elif i in replacements:replace_para(p,replacements[i])
    dest=OUT/'Physical_AI_Psychiatry_Supplementary_Information_v4.5.docx'
    doc.save(dest)
    return dest

def build_cover():
    doc=Document()
    sec=doc.sections[0];sec.left_margin=sec.right_margin=Inches(.87);sec.top_margin=Inches(.78);sec.bottom_margin=Inches(.74)
    normal=doc.styles['Normal'];normal.font.name='Arial';normal.font.size=Pt(10.4);normal.paragraph_format.space_after=Pt(8)
    paragraphs=[
      '[AUTHOR INPUT REQUIRED: date; corresponding author name, title, institution, and email]',
      'Editors\nnpj Digital Medicine',
      'Re: Submission of an Original Research Article',
      'Dear Editors,',
      f'We are pleased to submit “{TITLE}” for consideration as an Article in npj Digital Medicine.',
      ('Physical AI is moving toward psychiatric settings at a time when trials of socially assistive robots are producing clinically relevant signals and health systems are closely scrutinizing the safety and workforce implications of AI. An essential deployment question is whether benefits beyond a functionally matched screen justify the additional oversight, reliability, and physical-safety requirements of an embodied pathway.'),
      ('Our research develops a reproducible multiscale evaluation framework across longitudinal psychiatric monitoring and clinic intake. It integrates patient-centered outcomes with retention, alert detection, clinician verification work, service waiting, and operational burden. In the human-gated pathway, increased modeled response and improved high-acuity detection coexist with lower completion and longer waits. Neutral and skeptical analyses identify the conditions that reverse the response benefit, while a 1,024-point global sensitivity design isolates the most consequential assumptions. Together, these analyses establish a practical dual-gate decision framework for selecting trial endpoints, setting reliability and staffing targets, and prioritizing prospective validation.'),
      ('The Article is accompanied by six coordinated publication figures, four summary tables, full mathematical and operational model specifications, comprehensive parameter provenance files, and executable code. It presents transparent hypothesis-generating analysis with clearly delimited model-based inference, providing an operational framework that can be calibrated and externally assessed with future patient and clinic data.'),
      ('The submission builds on recent clinical trials and systematic reviews of care robots, evidence on clinician verification burden, and emerging preprint work on mental-health AI safety and robot-supported behavioral exercises. We believe its integration of clinical outcomes, workflow effects, and sensitivity-informed break-even criteria is especially relevant to npj Digital Medicine readers studying the safe translation of AI into patient care.'),
      '[AUTHOR INPUT REQUIRED: confirm authorship and approval, originality, related submissions, conflict declarations, ethics applicability, AI-use disclosure, repository archive DOI, and authorized license before sending.]',
      'Sincerely,\n[Corresponding author name and affiliations — AUTHOR INPUT REQUIRED]',
    ]
    for text in paragraphs:doc.add_paragraph(text)
    path=OUT/'Physical_AI_Psychiatry_Cover_Letter_v4.5.docx';doc.save(path);return path

if __name__=='__main__':
    main,words=build_main(); supp=build_supp();cover=build_cover()
    print('Wrote', main, supp, cover, 'abstract_words',words,'references',40+len(NEWREFS),'title_words',len(TITLE.split()))
